class GraphSys {
public:
#ifdef _USRDLL
    GraphSys();
    GraphSys(int unrecovered) {}
#endif
    virtual ~GraphSys();
    virtual int               init_app(void *config, const char *title, BufferBase *provider) = 0;
    virtual void              close_app() = 0;
    virtual void              cleanup_system() = 0;
    virtual void              show_app(void) = 0;
    virtual void              hide_app(void) = 0;
    virtual void              minimize_app(void) = 0;
    virtual void              maximize_app(void) = 0;
    virtual void             *get_window_handle(void);
    virtual void             *get_app_instance(void);
    virtual void              set_window_pos(int x, int y, int cx, int cy);
    virtual void              get_cursor_pos(int *px, int *py) = 0;
    virtual void              invalidate_rect(const Rect *r) = 0;
    virtual void              get_screen_dimensions(int *pw, int *ph) = 0;
    virtual void              get_window_rect(Rect *r) = 0;
    virtual void             *get_hdc(void) = 0;
    virtual int               Unimplemented16(char *);
    virtual int               init_device(int);
    virtual int               get_devices(void);
    virtual void              close_device(void);
    virtual int               init_display_quick_GL(int w, int h, int bpp) = 0;
    virtual int               SetDisplayModeToDesktop(int flag) = 0;
    virtual int               SetDisplayMode(int w, int h, int bpp) = 0;
    virtual int               SetDisplayModeWithRefresh(int w, int h, int bpp, bool bDefer, int freq) = 0;
    virtual int               init_display_quick(int w, int h, int bpp, bool bStore) = 0;
    virtual int               init_display(int nMode) = 0;
    virtual DisplayModeArray *get_display_modes() = 0;
    virtual int               setTemporaryResolution(int width, int height) = 0;
    virtual int               resetTemporaryResolution(void) = 0;
    virtual JGLFont          *get_font_data(FontBase *metrics) = 0;
    virtual JGLPalette       *get_palette_data(PaletteBase *client) = 0;
    virtual JGLBuffer        *get_buffer_data(BufferBase *owner, int memType) = 0;
    virtual JGLSprite        *get_sprite_data(JGLSprite **ppOwner, int memType) = 0;
    virtual int               get_light_data(int);
    virtual void              delete_font_data(GSFont *p) = 0;
    virtual void              delete_buffer_data(JGLBuffer *p) = 0;
    virtual void              delete_palette_data(JGLPalette *p) = 0;
    virtual void              delete_sprite_data(GSSprite *p) = 0;
    virtual void              delete_light_data(int);
    virtual void              set_sprite_scale(int nX, int nY, int nDenom) = 0;
    virtual void              get_sprite_scale(int *pa, int *pb, int *pc) = 0;
    virtual int               flip(Rect *rect) = 0;
    virtual int               screen_width(void) = 0;
    virtual int               screen_height(void) = 0;
    virtual int               screen_bpp(void) = 0;
    virtual int               screen_mask(void) = 0;
    virtual int               init_font_system(void) = 0;
    virtual void              close_font_system(void) = 0;
    virtual void              init_palette_system(PaletteBase *pBase, PaletteBase *pAlt) = 0;
    virtual void              close_palette_system(void) = 0;
    virtual int               clear_buffer();
    virtual int               begin_scene();
    virtual int               end_scene();
    virtual int               create_verts(void **, ulong);
    virtual int               set_material(int);
    virtual int               set_world_transform(int);
    virtual int               set_camera_transform(int);
    virtual int               set_projection(float, float, float);
    virtual int               load_texture(char *);
    virtual int               set_texture(int, char *);
    virtual int               zbuffer_enable(int);
    virtual int               zwrite_enable(int);
    virtual int               src_blend_enable(int);
    virtual int               specular_enable(int);
    virtual int               read_x_file(char *, int, int, int, int, int);
    virtual int               copy_verts(void *, int, int, int);
    virtual int               render_verts(void *, int);
    virtual int               set_src_blend(int);
    virtual int               set_dst_blend(int);
    virtual int               set_cull_mode(int);
    virtual int               set_fill_mode(int);
    virtual int               set_shade_mode(int);
    virtual int               do_timer(void) = 0;
    virtual void              wait_task(void) = 0;
    virtual int               do_task(void) = 0;
    virtual int               do_non_input(void) = 0;
    virtual int               do_draw(void) = 0;
    virtual int               do_key(void) = 0;
    virtual int               do_char(void) = 0;
    virtual int               do_mouse(void) = 0;
    virtual int               do_mouse_move(void) = 0;
    virtual int               do_mouse_stroke(void) = 0;
    virtual void              flush_keyboard(void) = 0;
    virtual void              flush_mouse(void) = 0;
    virtual void              flush_timer(void) = 0;
    virtual void              setCopyDataCallBack(int (*p)(unsigned int, long));
};
